Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
#include <limits>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    long long x, y, n;
    cin >> x >> y >> n;

    long double ratio = static_cast<long double>(x) / y;
    long long candidate_num = 0, candidate_den = 1;
    long double smallest_error = numeric_limits<long double>::max();

    for (long long denominator = 1; denominator <= n; ++denominator) {
        long double target = ratio * denominator;
        long long floor_num = static_cast<long long>(floor(target));
        long long ceil_num = static_cast<long long>(ceil(target));

        auto compute_error = [ratio](long long num, long long den) -> long double {
            return abs(ratio - static_cast<long double>(num) / den);
        };

        long double error_floor = compute_error(floor_num, denominator);
        long double error_ceil = compute_error(ceil_num, denominator);

        if (error_floor < smallest_error) {
            smallest_error = error_floor;
            candidate_num = floor_num;
            candidate_den = denominator;
        }
        if (error_ceil < smallest_error) {
            smallest_error = error_ceil;
            candidate_num = ceil_num;
            candidate_den = denominator;
        }
    }

    cout << candidate_num << '/' << candidate_den;
    return 0;
}
